async def _get_or_create_category(db, meta: dict) -> Category:
    result = await db.execute(select(Category).where(Category.name == meta["name"]))
    category = result.scalar_one_or_none()
    if category is not None:
        return category
    category = Category(
        name=meta["name"],
        icon_name=meta["icon_name"],
        color_key=meta["color_key"],
        sort_order=meta["sort_order"],
        is_active=True,
    )
    db.add(category)
    await db.flush()
    return category


async def seed() -> None:
    created = 0
    skipped = 0
    async with AsyncSessionLocal() as db:
        for meta in CATEGORIES:
            category = await _get_or_create_category(db, meta)
            existing = await db.execute(
                select(Question.question_text).where(Question.category_id == category.id)
            )
            existing_texts = {row[0] for row in existing.all()}
            for question_text, options, correct_index in QUESTIONS.get(meta["name"], []):
                if question_text in existing_texts:
                    skipped += 1
                    continue
                db.add(
                    Question(
                        category_id=category.id,
                        question_text=question_text,
                        options=options,
                        correct_option_index=correct_index,
                        is_active=True,
                    )
                )
                created += 1
        await db.commit()
    print(f"Yaratildi: {created} yangi savol. O'tkazib yuborildi (allaqachon mavjud edi): {skipped}.")


if __name__ == "__main__":
    asyncio.run(seed())
